SET NAMES utf8mb4;
-- M4 B2: solo datos; no ejecuta conciliacion/triage ni retira GET_LOCK de HC.
-- DDL confirma implicitamente. Inspeccion por paso, sin rollback global.
-- Rutina transitoria de diagnostico; una sola sentencia sin DELIMITER, CLI/PDO.
DROP PROCEDURE IF EXISTS zooki_m4_08_error;
CREATE PROCEDURE zooki_m4_08_error(IN mensaje VARCHAR(128)) SQL SECURITY INVOKER SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = mensaje;
SET @m4_ddl = IF(EXISTS(SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='planes'), 'DO 0', CONCAT('CALL zooki_m4_08_error(', QUOTE(CONCAT('M4-08 falta tabla v2 planes')), ')'));
PREPARE m4_sentencia FROM @m4_ddl;
EXECUTE m4_sentencia;
DEALLOCATE PREPARE m4_sentencia;
